#include <curl/curl.h>
#include <psp2/io/fcntl.h>
#include <ctype.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include "download.h"

#define FM_USER_AGENT "FileManager/0.9 (PS Vita)"
#define FM_WRITE_BUFFER (256 * 1024)

typedef struct HeaderState { char disposition[384]; char contentType[96]; } HeaderState;
typedef struct DownloadState { SceUID fd; unsigned char *buffer; size_t used; int failed; DownloadProgress progress; DownloadCancel cancel; } DownloadState;
static int s_curlReady;

static int ensureCurl(void) { if (!s_curlReady) { if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) return -1; s_curlReady=1; } return 0; }
static const char *findCase(const char *s,const char*n){size_t l=strlen(n);for(;*s;s++)if(!strncasecmp(s,n,l))return s;return NULL;}
static int hexValue(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return-1;}
static void decodeFilename(char*out,size_t cap,const char*src,size_t len){size_t n=0;while(len&&(*src==' '||*src=='\t'||*src=='"')){src++;len--;}while(len&&n+1<cap){char c=*src++;len--;if(c=='"'||c==';'||c=='\r'||c=='\n')break;if(c=='%'&&len>=2){int a=hexValue(src[0]),b=hexValue(src[1]);if(a>=0&&b>=0){c=(char)((a<<4)|b);src+=2;len-=2;}}if((unsigned char)c<0x20||strchr("\\/:*?\"<>|",c))c='_';out[n++]=c;}while(n&&(out[n-1]==' '||out[n-1]=='.'))n--;out[n]=0;}
static void filenameFromDisposition(const char*v,char*out,size_t cap){out[0]=0;const char*k=findCase(v,"filename*=");if(k){k+=10;const char*e=strstr(k,"''");if(e)k=e+2;decodeFilename(out,cap,k,strlen(k));if(out[0])return;}k=findCase(v,"filename=");if(k)decodeFilename(out,cap,k+9,strlen(k+9));}
static void filenameFromUrl(const char*u,char*out,size_t cap){const char*s=strrchr(u,'/');const char*n=s&&s[1]?s+1:"";decodeFilename(out,cap,n,strcspn(n,"?#"));}
static int urlLooksLikeFile(const char*n){const char*d=strrchr(n,'.');return d&&d[1]&&strcasecmp(d,".html")&&strcasecmp(d,".htm")&&strcasecmp(d,".php")&&strcasecmp(d,".asp")&&strcasecmp(d,".aspx");}

static size_t headerCallback(char *ptr,size_t size,size_t count,void *userdata){size_t n=size*count;HeaderState*h=(HeaderState*)userdata;if(!h||!n)return n;const char*colon=memchr(ptr,':',n);if(!colon)return n;size_t key=(size_t)(colon-ptr),off=key+1;while(off<n&&(ptr[off]==' '||ptr[off]=='\t'))off++;size_t len=n-off;while(len&&(ptr[off+len-1]=='\r'||ptr[off+len-1]=='\n'))len--;char*out=NULL;size_t cap=0;if(key==19&&!strncasecmp(ptr,"Content-Disposition",19)){out=h->disposition;cap=sizeof(h->disposition);}else if(key==12&&!strncasecmp(ptr,"Content-Type",12)){out=h->contentType;cap=sizeof(h->contentType);}if(out){if(len>=cap)len=cap-1;memcpy(out,ptr+off,len);out[len]=0;}return n;}
static void commonOptions(CURL*c,const char*url,HeaderState*h){curl_easy_setopt(c,CURLOPT_URL,url);curl_easy_setopt(c,CURLOPT_USERAGENT,FM_USER_AGENT);curl_easy_setopt(c,CURLOPT_FOLLOWLOCATION,1L);curl_easy_setopt(c,CURLOPT_MAXREDIRS,8L);curl_easy_setopt(c,CURLOPT_CONNECTTIMEOUT,20L);curl_easy_setopt(c,CURLOPT_LOW_SPEED_LIMIT,1L);curl_easy_setopt(c,CURLOPT_LOW_SPEED_TIME,30L);curl_easy_setopt(c,CURLOPT_NOSIGNAL,1L);curl_easy_setopt(c,CURLOPT_SSL_VERIFYPEER,0L);curl_easy_setopt(c,CURLOPT_SSL_VERIFYHOST,0L);if(h){curl_easy_setopt(c,CURLOPT_HEADERFUNCTION,headerCallback);curl_easy_setopt(c,CURLOPT_HEADERDATA,h);}}

int inspectDownloadUrl(const char *url,DownloadInfo *info){if(!url||!info||ensureCurl()<0)return-1;memset(info,0,sizeof(*info));HeaderState h;memset(&h,0,sizeof(h));CURL*c=curl_easy_init();if(!c)return-1;commonOptions(c,url,&h);curl_easy_setopt(c,CURLOPT_NOBODY,1L);CURLcode r=curl_easy_perform(c);long status=0;double total=0;char*effective=NULL;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);curl_easy_getinfo(c,CURLINFO_CONTENT_LENGTH_DOWNLOAD,&total);curl_easy_getinfo(c,CURLINFO_EFFECTIVE_URL,&effective);if(r==CURLE_OK&&status>=200&&status<300){if(total>0)info->contentLength=(uint64_t)total;strncpy(info->contentType,h.contentType,sizeof(info->contentType)-1);filenameFromDisposition(h.disposition,info->filename,sizeof(info->filename));if(!info->filename[0])filenameFromUrl(effective?effective:url,info->filename,sizeof(info->filename));if(!info->filename[0])strcpy(info->filename,"download.bin");int attachment=findCase(h.disposition,"filename=")||findCase(h.disposition,"filename*=");int html=!strncasecmp(info->contentType,"text/html",9)||!strncasecmp(info->contentType,"application/xhtml",17);info->isFile=attachment||(!html&&info->contentType[0])||urlLooksLikeFile(info->filename);r=CURLE_OK;}curl_easy_cleanup(c);return r==CURLE_OK&&status>=200&&status<300?0:(status>=400?-(int)status:-(int)r-1);}

static int flushDownload(DownloadState*d){if(!d->used)return 0;int n=sceIoWrite(d->fd,d->buffer,d->used);if(n!=(int)d->used){d->failed=1;return-1;}d->used=0;return 0;}
static size_t writeCallback(void*ptr,size_t size,size_t count,void*userdata){DownloadState*d=(DownloadState*)userdata;size_t total=size*count,off=0;while(off<total){size_t n=total-off;if(n>FM_WRITE_BUFFER-d->used)n=FM_WRITE_BUFFER-d->used;memcpy(d->buffer+d->used,(unsigned char*)ptr+off,n);d->used+=n;off+=n;if(d->used==FM_WRITE_BUFFER&&flushDownload(d)<0)return 0;}return total;}
static int progressCallback(void*userdata,curl_off_t total,curl_off_t now,curl_off_t upTotal,curl_off_t upNow){(void)upTotal;(void)upNow;DownloadState*d=(DownloadState*)userdata;if(d->progress)d->progress((uint64_t)now,total>0?(uint64_t)total:0);return d->cancel&&d->cancel()?1:0;}

int downloadUrlEx(const char*url,const char*destination,DownloadProgress progress,DownloadCancel cancel){if(!url||!destination||ensureCurl()<0)return-1;DownloadState d;memset(&d,0,sizeof(d));d.fd=-1;d.progress=progress;d.cancel=cancel;d.buffer=malloc(FM_WRITE_BUFFER);if(!d.buffer)return-1;d.fd=sceIoOpen(destination,SCE_O_WRONLY|SCE_O_CREAT|SCE_O_TRUNC,0777);if(d.fd<0){free(d.buffer);return d.fd;}HeaderState h;memset(&h,0,sizeof(h));CURL*c=curl_easy_init();if(!c){sceIoClose(d.fd);free(d.buffer);sceIoRemove(destination);return-1;}commonOptions(c,url,&h);curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,writeCallback);curl_easy_setopt(c,CURLOPT_WRITEDATA,&d);curl_easy_setopt(c,CURLOPT_NOPROGRESS,0L);curl_easy_setopt(c,CURLOPT_XFERINFOFUNCTION,progressCallback);curl_easy_setopt(c,CURLOPT_XFERINFODATA,&d);curl_easy_setopt(c,CURLOPT_BUFFERSIZE,256*1024L);CURLcode r=curl_easy_perform(c);long status=0;curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&status);if(r==CURLE_OK&&status>=200&&status<300)flushDownload(&d);curl_easy_cleanup(c);sceIoClose(d.fd);free(d.buffer);if(r!=CURLE_OK||status<200||status>=300||d.failed){sceIoRemove(destination);if(r==CURLE_ABORTED_BY_CALLBACK)return 1;return status>=400?-(int)status:-(int)r-1;}return 0;}
int downloadUrl(const char*u,const char*d,DownloadProgress p){return downloadUrlEx(u,d,p,NULL);}
